function Sidebar({ path, collapsed, onToggle, mobileOpen, onMobileClose, navigate }: { path: string; collapsed: boolean; onToggle: () => void; mobileOpen: boolean; onMobileClose: () => void; navigate: (path: string) => void }) {
  const [customerExpanded, setCustomerExpanded] = useState(true);
  const [requirementsExpanded, setRequirementsExpanded] = useState(true);
  const isRequirement = path.startsWith("/requirement-") || path === "/requirements-list" || path === "/clarifications";
  const renderNav = (items: typeof customerNavItems) => <div className="nav-list">{items.map(({ label, path: itemPath, icon: Icon, badge }) => { const active = path === itemPath || (itemPath === "/projects" && path.startsWith("/projects/")); return <button key={itemPath} className={`nav-item ${active ? "active" : ""}`} onClick={() => { navigate(itemPath); onMobileClose(); }}><Icon size={16} /><span>{label}</span>{badge && <span className="nav-badge">{badge}</span>}</button> })}</div>;
  return <><aside className={`sidebar ${collapsed ? "collapsed" : ""} ${mobileOpen ? "mobile-open" : ""}`}><div className="sidebar-top"><Logo /><button className="sidebar-close" onClick={onMobileClose}><X size={18} /></button></div><div className="workspace-label">WORKSPACE</div><button className="workspace-parent" onClick={() => setCustomerExpanded(v => !v)}><span className="workspace-parent-icon"><Workflow size={16} /></span><span>Customer Discovery</span><ChevronDown size={15} className={customerExpanded ? "rotate-180" : ""} /></button>{customerExpanded && renderNav(customerNavItems)}<button className={`workspace-parent requirement-parent ${isRequirement ? "selected" : ""}`} onClick={() => setRequirementsExpanded(v => !v)}><span className="workspace-parent-icon requirement-icon"><Sparkles size={15} /></span><span>Requirement Intelligence</span><ChevronDown size={15} className={requirementsExpanded ? "rotate-180" : ""} /></button>{requirementsExpanded && renderNav(requirementNavItems)}<div className="sidebar-divider" /><div className="workspace-label">MANAGEMENT</div><button className={`nav-item ${path === "/settings" ? "active" : ""}`} onClick={() => { navigate("/settings"); onMobileClose(); }}><Settings size={16} /><span>Settings</span></button><button className={`nav-item ${path === "/profile" ? "active" : ""}`} onClick={() => { navigate("/profile"); onMobileClose(); }}><UserRound size={16} /><span>Profile</span></button><div className="sidebar-spacer" /><div className="sidebar-tip"><div className="tip-spark"><Sparkles size={15} /></div><strong>{isRequirement ? "Make requirements ready." : "Make your next question count."}</strong><span>{isRequirement ? "CLARIVON AI found 3 open clarifications in your active project." : "CLARIVON AI found 4 context gaps in your active project."}</span><button onClick={() => navigate(isRequirement ? "/clarifications" : "/discovery")}>{isRequirement ? "Review clarifications" : "Review gaps"} <ArrowRight size={13} /></button></div><div className="profile-mini"><div className="avatar">JD</div><div className="profile-mini-info"><strong>John Doe</strong><span>Product Manager</span></div><button onClick={() => navigate("/profile")}><MoreHorizontal size={17} /></button></div><button className="collapse-button" onClick={onToggle}><ChevronRight size={16} className={!collapsed ? "rotate-180" : ""} /><span>Collapse sidebar</span></button></aside>{mobileOpen && <button className="sidebar-overlay" onClick={onMobileClose} aria-label="Close navigation" />}</>;
}
function Topbar({ title, subtitle, onMenu, navigate, onToast }: { title?: string; subtitle?: string; onMenu: () => void; navigate: (path: string) => void; onToast: (message: string) => void }) {
  return <header className="topbar"><div className="topbar-title"><button className="mobile-menu" onClick={onMenu}><Menu size={20} /></button><div><h1>{title || "Customer Discovery"}</h1>{subtitle && <p>{subtitle}</p>}</div></div><div className="topbar-actions"><div className="topbar-search"><Search size={16} /><input placeholder="Search workspace" /><kbd>⌘ K</kbd></div><button className="icon-button" onClick={() => onToast("You’re all caught up.")}><Bell size={18} /><span className="notification-dot" /></button><button className="topbar-avatar" onClick={() => navigate("/profile")}>JD</button></div></header>;
}

function AppShell({ path, navigate, children, onToast }: { path: string; navigate: (path: string) => void; children: ReactNode; onToast: (message: string) => void }) {
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  return <div className="app-shell"><Sidebar path={path} collapsed={collapsed} onToggle={() => setCollapsed(v => !v)} mobileOpen={mobileOpen} onMobileClose={() => setMobileOpen(false)} navigate={navigate} /><div className={`app-main ${collapsed ? "sidebar-collapsed" : ""}`}><Topbar title={path.startsWith("/requirement") || path === "/requirements-list" || path === "/clarifications" ? "Requirement Intelligence" : "Customer Discovery"} onMenu={() => setMobileOpen(true)} navigate={navigate} onToast={onToast} /><div className="page-content">{children}</div></div></div>;
}

function PageHeader({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle: string; action?: ReactNode }) {
  return <div className="page-header"><div><div className="eyebrow">{eyebrow || "CUSTOMER DISCOVERY"}</div><h2>{title}</h2><p>{subtitle}</p></div>{action && <div className="page-header-action">{action}</div>}</div>;
}

function StatCard({ label, value, delta, icon: Icon, accent }: { label: string; value: string; delta: string; icon: any; accent: string }) {
  return <div className="stat-card"><div className={`stat-icon ${accent}`}><Icon size={18} /></div><div className="stat-card-body"><span>{label}</span><strong>{value}</strong><small><TrendingUp size={12} /> {delta}</small></div><div className="stat-sparkline"><span style={{ height: "28%" }} /><span style={{ height: "45%" }} /><span style={{ height: "38%" }} /><span style={{ height: "72%" }} /><span style={{ height: "55%" }} /><span style={{ height: "88%" }} /></div></div>;
}

function WorkflowVisualization() {
  const stages = [["01", "Customer conversation", "Raw customer voice", "input"], ["02", "AI analysis", "Pattern recognition", "ai"], ["03", "Customer goal", "What they want", "goal"], ["04", "Stated problem", "What they say", "problem"], ["05", "Root problem", "What may be underneath", "root"], ["06", "Symptoms + assumptions", "Separate signal from cause", "signal"], ["07", "Evidence", "Build the case", "evidence"], ["08", "Missing information", "Find context gaps", "missing"], ["09", "Follow-up questions", "Ask what matters", "questions"], ["10", "Problem validation", "Know when to act", "validation"]];
  return <div className="workflow-visualization">{stages.map(([number, title, subtitle, tone], index) => <div className={`workflow-stage stage-${tone}`} key={title}><div className="stage-number">{number}</div><div className="stage-content"><strong>{title}</strong><span>{subtitle}</span></div>{index < stages.length - 1 && <ArrowDown className="stage-arrow" size={14} />}</div>)}</div>;
}

function DashboardPage({ navigate }: { navigate: (path: string) => void }) {
  return <><PageHeader eyebrow="TUESDAY, SEPTEMBER 10 · 09:41" title="Good morning, John" subtitle="Discover the real problems behind your customer conversations." action={<Button onClick={() => navigate("/discovery")}><Sparkles size={16} /> New analysis</Button>} /><div className="stats-grid"><StatCard label="Active projects" value="12" delta="3 this month" icon={FolderKanban} accent="blue" /><StatCard label="Conversations analyzed" value="48" delta="12% vs last month" icon={MessageSquareText} accent="violet" /><StatCard label="Problems discovered" value="36" delta="8 high confidence" icon={Lightbulb} accent="amber" /><StatCard label="Questions generated" value="124" delta="18 ready to ask" icon={MessageCircleQuestion} accent="mint" /></div><div className="dashboard-grid"><section className="surface-card workflow-card"><div className="card-heading"><div><span className="card-kicker"><span className="live-dot" /> YOUR DISCOVERY WORKFLOW</span><h3>From conversation to conviction</h3><p>Every analysis follows the same intelligence path—so nothing important gets skipped.</p></div><button className="more-button"><MoreHorizontal size={18} /></button></div><WorkflowVisualization /><div className="workflow-footer"><div><span className="workflow-footer-dot" /> <strong>4 active analyses</strong><span>across 3 projects</span></div><button className="text-button" onClick={() => navigate("/discovery")}>Start a new analysis <ArrowRight size={14} /></button></div></section><aside className="surface-card insight-card"><div className="insight-card-head"><div className="ai-orb"><Sparkles size={17} /></div><span>CLARIVON AI</span><span className="ai-status">Online</span></div><h3>What your workspace is telling you</h3><div className="ai-callout"><div className="callout-number">01</div><p>Transfer reliability appears in <strong>4 recent conversations</strong> across Retail Banking App.</p></div><div className="ai-callout"><div className="callout-number">02</div><p>Problems with specific behavioral evidence are <strong>2.4× more confident</strong>.</p></div><button className="text-button" onClick={() => navigate("/intelligence")}>Explore intelligence <ArrowRight size={14} /></button></aside></div><section className="dashboard-lower"><div className="surface-card projects-card"><div className="card-heading compact"><div><span className="card-kicker">KEEP THE MOMENTUM</span><h3>Recent projects</h3></div><button className="text-button" onClick={() => navigate("/projects")}>View all <ArrowRight size={14} /></button></div><div className="projects-table"><div className="table-head"><span>Project</span><span>Discovery health</span><span>Status</span><span>Updated</span><span /></div>{projects.slice(0, 3).map(project => <button className="project-row" key={project.name} onClick={() => navigate("/projects/retail-banking")}><div className="project-cell"><div className={`project-logo ${project.tone}`}>{project.name.slice(0, 1)}</div><div><strong>{project.name}</strong><span>{project.customer} · {project.conversations} conversations</span></div></div><div className="health-cell"><div><ProgressBar value={project.confidence} color={project.tone === "mint" ? "mint" : project.tone === "violet" ? "violet" : "blue"} /><strong>{project.confidence}%</strong></div><span>{project.problems} problems</span></div><Badge tone={project.status === "Validated" ? "mint" : "blue"}>{project.status}</Badge><span className="updated-cell">{project.updated}</span><ChevronRight size={16} /></button>)}</div></div><div className="surface-card quick-card"><div className="card-heading compact"><div><span className="card-kicker">MOVE FASTER</span><h3>Quick actions</h3></div></div><button onClick={() => navigate("/projects")}><span className="quick-icon blue"><Plus size={17} /></span><span><strong>New project</strong><small>Organize a new research initiative</small></span><ArrowRight size={15} /></button><button onClick={() => navigate("/discovery")}><span className="quick-icon violet"><Sparkles size={17} /></span><span><strong>New analysis</strong><small>Analyze a customer conversation</small></span><ArrowRight size={15} /></button><button onClick={() => navigate("/projects/retail-banking")}><span className="quick-icon mint"><ArrowRight size={17} /></span><span><strong>Continue discovery</strong><small>Retail Banking App · 87% confidence</small></span><ArrowRight size={15} /></button></div></section></>;
}

function DiscoveryPage({ onToast }: { onToast: (message: string) => void }) {
  const [tab, setTab] = useState("Conversation");
  const [text, setText] = useState("I spend too much time trying to transfer money through the mobile app. I usually have to try multiple times, and sometimes I just call customer support.");
  const [status, setStatus] = useState<"idle" | "loading" | "results">("idle");
  const [saved, setSaved] = useState(false);
  const [questionCopied, setQuestionCopied] = useState(false);
  useEffect(() => { if (status !== "loading") return; const t = window.setTimeout(() => setStatus("results"), 2300); return () => window.clearTimeout(t); }, [status]);
  const analyze = () => { if (!text.trim()) { onToast("Add a customer conversation first."); return; } setStatus("loading"); };
  if (status === "loading") return <div className="analysis-loading"><div className="analysis-loading-orb"><Sparkles size={28} /></div><div className="eyebrow">CLARIVON AI · LIVE ANALYSIS</div><h2>Listening for what’s underneath.</h2><p>We’re moving from the customer’s words to a clearer understanding of the problem.</p><div className="loading-steps">{["Reading customer statements", "Identifying customer goals", "Detecting problems", "Separating symptoms from root causes", "Detecting assumptions", "Extracting evidence", "Finding missing information"].map((step, index) => <div className={`loading-step ${index < 4 ? "done" : index === 4 ? "current" : ""}`} key={step}><span>{index < 4 ? <Check size={13} /> : index === 4 ? <span className="loading-pulse" /> : <Circle size={12} />}</span>{step}{index < 4 && <small>complete</small>}</div>)}</div><div className="loading-progress"><ProgressBar value={67} color="violet" /><span>Almost done · mapping evidence to context gaps</span></div></div>;
  if (status === "results") return <AnalysisResults text={text} saved={saved} setSaved={setSaved} questionCopied={questionCopied} setQuestionCopied={setQuestionCopied} onToast={onToast} onReset={() => setStatus("idle")} />;
  return <><PageHeader eyebrow="NEW ANALYSIS · RETAIL BANKING APP" title="New customer discovery analysis" subtitle="Analyze a customer conversation and uncover the problem behind what they said." action={<div className="analysis-progress-pill"><span>STEP 01</span><strong>Capture conversation</strong><span>of 04</span></div>} /><div className="analysis-layout"><main><div className="surface-card project-picker"><div className="card-heading compact"><div><span className="card-kicker">PROJECT</span><h3>Where should we save this analysis?</h3></div><Button variant="secondary" onClick={() => onToast("Project creation modal opened.")}><Plus size={15} /> New project</Button></div><div className="select-like"><div className="project-logo blue">R</div><div><strong>Retail Banking App</strong><span>FinBank · 8 conversations</span></div><ChevronDown size={17} /></div></div><div className="surface-card conversation-card"><div className="card-heading"><div><span className="card-kicker">CAPTURE CUSTOMER VOICE</span><h3>What did the customer say?</h3><p>Start with their words. CLARIVON will help you separate the signal from the noise.</p></div><div className="conversation-count">{text.length}<span>/ 10,000</span></div></div><div className="analysis-tabs">{["Conversation", "Interview Notes", "Email", "Meeting Notes", "Upload Document"].map(item => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{item === "Upload Document" && <Upload size={14} />}{item}</button>)}</div>{tab === "Upload Document" ? <div className="upload-zone"><div className="upload-icon"><Upload size={22} /></div><strong>Drop a document here</strong><span>PDF, DOCX, or TXT · up to 20 MB</span><Button variant="secondary" onClick={() => onToast("File picker opened.")}>Choose file</Button></div> : <textarea value={text} onChange={e => setText(e.target.value)} placeholder="Paste the customer conversation, interview notes, or meeting transcript here..." />}{tab !== "Upload Document" && <div className="conversation-footer"><div><span className="input-tip"><Lightbulb size={14} /> Tip</span> Include the customer’s exact words for stronger evidence.</div><Button onClick={analyze}><Sparkles size={16} /> Analyze with AI</Button></div>}</div><div className="analysis-note"><Sparkles size={16} /><div><strong>This is more than summarization.</strong><p>CLARIVON will identify goals, stated and root problems, symptoms, assumptions, evidence, missing context, and the questions that will make your next conversation count.</p></div></div></main><aside className="analysis-side"><div className="side-progress surface-card"><div className="side-progress-head"><strong>Discovery flow</strong><span>1 of 4</span></div><ProgressBar value={25} color="blue" /><div className="mini-flow"><div className="mini-flow-item active"><span><Check size={12} /></span><div><strong>Capture</strong><small>Add customer voice</small></div></div><div className="mini-flow-item"><span>2</span><div><strong>Analyze</strong><small>Find patterns and signals</small></div></div><div className="mini-flow-item"><span>3</span><div><strong>Discover</strong><small>Move below the surface</small></div></div><div className="mini-flow-item"><span>4</span><div><strong>Validate</strong><small>Know what to ask next</small></div></div></div></div><div className="side-ai surface-card"><div className="insight-card-head"><div className="ai-orb"><Sparkles size={15} /></div><span>AI ASSISTANT</span></div><p>“The strongest analyses include specific moments, workarounds, or quotes—not just a high-level summary.”</p><span className="ai-sig">— CLARIVON AI</span></div></aside></div></>;
}

function ConfidenceRing({ value, label }: { value: number; label?: string }) {
  return <div className="confidence-wrap"><div className="confidence-ring"><div><strong>{value}</strong><span>%</span></div></div>{label && <span>{label}</span>}</div>;
}

function AnalysisResults({ text, saved, setSaved, questionCopied, setQuestionCopied, onToast, onReset }: { text: string; saved: boolean; setSaved: (v: boolean) => void; questionCopied: boolean; setQuestionCopied: (v: boolean) => void; onToast: (message: string) => void; onReset: () => void }) {
  const copyQuestions = () => { navigator.clipboard?.writeText(analysisData.questions.map((q, i) => `${i + 1}. ${q[0]}`).join("\n")); setQuestionCopied(true); onToast("Questions copied to clipboard."); };
  return <div className="results-page"><div className="results-top"><div><div className="eyebrow">ANALYSIS COMPLETE · RETAIL BANKING APP</div><h2>Here’s what we heard.</h2><p>CLARIVON looked beyond the literal wording to map the customer’s goal, problem, evidence, and next best questions.</p></div><div className="results-actions"><Button variant="secondary" onClick={onReset}><Pencil size={15} /> Edit conversation</Button><Button variant="secondary" onClick={() => { window.history.pushState({}, "", "/requirement-analysis?from=discovery"); window.dispatchEvent(new PopStateEvent("popstate")); onToast("Customer discovery findings are ready for requirement analysis."); }}><Workflow size={15} /> Convert findings</Button><Button onClick={() => { setSaved(true); onToast("Discovery saved successfully."); }}>{saved ? <Check size={15} /> : <Download size={15} />} {saved ? "Saved" : "Save discovery"}</Button></div></div><div className="results-meta"><span><span className="live-dot" /> AI analysis complete</span><span>Retail Banking App</span><span>Conversation #09</span><span>Analyzed just now</span></div><div className="results-grid"><div className="results-main"><section className="result-block accent-blue"><div className="result-label"><span className="result-num">01</span><div><span className="card-kicker">CUSTOMER GOAL</span><h3>What does the customer want?</h3></div><Badge tone="mint">94% confidence</Badge></div><p className="result-lead">{analysisData.goal}</p><div className="result-source"><MessageSquareText size={15} /><span>Inferred from the customer’s desire to complete the task independently.</span></div></section><section className="result-block accent-amber"><div className="result-label"><span className="result-num">02</span><div><span className="card-kicker">STATED PROBLEM</span><h3>What are they saying is wrong?</h3></div></div><p className="result-lead">{analysisData.stated}</p><div className="evidence-highlight"><span>“I usually have to try multiple times.”</span><small>Direct customer evidence</small></div></section><section className="result-block accent-violet root-problem-block"><div className="result-label"><span className="result-num">03</span><div><span className="card-kicker">ROOT PROBLEM · AI REASONING</span><h3>What may be underneath?</h3></div><ConfidenceRing value={89} label="confidence" /></div><p className="result-lead">{analysisData.root}</p><div className="reasoning-box"><div className="reasoning-icon"><Lightbulb size={16} /></div><div><strong>Why this is deeper than the stated problem</strong><p>{analysisData.rootExplanation}</p></div></div></section><section className="result-block"><div className="result-label"><span className="result-num">04</span><div><span className="card-kicker">SYMPTOMS DETECTED</span><h3>Signals showing up in the conversation</h3></div><Badge tone="violet">5 detected</Badge></div><div className="symptoms-grid">{analysisData.symptoms.map((symptom, i) => <div className="symptom-chip" key={symptom}><span>{String(i + 1).padStart(2, "0")}</span><strong>{symptom}</strong><small>{i < 2 ? "High signal" : "Supporting signal"}</small></div>)}</div></section><section className="result-block"><div className="result-label"><span className="result-num">05</span><div><span className="card-kicker">ASSUMPTION DETECTED</span><h3>What might we be assuming?</h3></div><Badge tone="amber">72% · Not confirmed</Badge></div><div className="assumption-card"><div className="assumption-icon"><HelpCircle size={18} /></div><div><strong>Customers understand the terminology used in the transfer process.</strong><p>This assumption may be influencing the interpretation but is not explicitly supported by the conversation.</p></div></div></section><section className="result-block"><div className="result-label"><span className="result-num">06</span><div><span className="card-kicker">EVIDENCE</span><h3>What supports these findings?</h3></div></div><div className="evidence-list">{analysisData.evidence.map(([quote, interpretation]) => <div className="evidence-row" key={quote}><div className="evidence-quote"><span>CUSTOMER STATEMENT</span><p>{quote}</p></div><ArrowRight size={17} /><div className="evidence-interpretation"><span>AI INTERPRETATION</span><p>{interpretation}</p></div></div>)}</div></section><section className="result-block missing-block"><div className="result-label"><span className="result-num">07</span><div><span className="card-kicker">MISSING INFORMATION</span><h3>What do we still need to know?</h3></div><Badge tone="rose">4 context gaps</Badge></div><div className="missing-grid">{[["Frequency", "We don’t know how often this problem occurs.", "High"], ["Customer segment", "Which types of customers are most affected?", "High"], ["Business impact", "What happens when the transfer fails?", "Medium"], ["Current workaround", "What do customers do instead?", "Medium"]].map(([title, desc, priority]) => <div className="missing-card" key={title}><div><strong>{title}</strong><Badge tone={priority === "High" ? "rose" : "amber"}>{priority} priority</Badge></div><p>{desc}</p></div>)}</div></section><section className="result-block questions-block"><div className="result-label"><span className="result-num">08</span><div><span className="card-kicker">AI FOLLOW-UP QUESTIONS</span><h3>Ask what matters next.</h3></div><div className="question-actions"><Button variant="secondary" onClick={copyQuestions}>{questionCopied ? <Check size={14} /> : <Copy size={14} />} {questionCopied ? "Copied" : "Copy questions"}</Button><Button variant="ghost" onClick={() => onToast("Question added to your discovery list.")}><Plus size={14} /> Add question</Button></div></div><p className="section-supporting">CLARIVON identified information that is still missing. Ask these questions in your next customer conversation.</p><div className="question-list">{analysisData.questions.map(([question, priority, purpose], i) => <div className="question-row" key={question}><span className="question-number">0{i + 1}</span><div className="question-copy"><strong>{question}</strong><span>{purpose}</span></div><Badge tone={priority === "High" ? "rose" : "amber"}>{priority}</Badge><button onClick={() => { navigator.clipboard?.writeText(question); onToast("Question copied."); }}><Copy size={15} /></button></div>)}</div></section></div><aside className="results-side"><div className="surface-card validation-card"><div className="card-kicker">PROBLEM VALIDATION</div><h3>Do we understand enough to act?</h3><div className="validation-rings"><ConfidenceRing value={87} label="Problem confidence" /><ConfidenceRing value={92} label="Customer evidence" /><ConfidenceRing value={85} label="Problem clarity" /></div><div className="validation-stat"><div><span>Context completeness</span><strong>78%</strong></div><ProgressBar value={78} color="blue" /></div><div className="validation-stat"><div><span>Validation needed</span><strong>21%</strong></div><ProgressBar value={21} color="amber" /></div><div className="validation-summary"><ShieldCheck size={16} /><p>The available evidence strongly supports the problem, but more information is needed about frequency, affected customer segments, and business impact.</p></div></div><div className="surface-card assistant-card"><div className="insight-card-head"><div className="ai-orb"><Sparkles size={15} /></div><span>CLARIVON AI</span></div><h3>One thing to carry forward</h3><p>“Ask about the last failed transfer—not the average experience. Specific moments reveal the journey.”</p><button className="text-button" onClick={() => onToast("Follow-up prompt saved to your questions.")}>Save as prompt <ArrowRight size={14} /></button></div><div className="surface-card source-card"><div className="card-kicker">SOURCE CONVERSATION</div><div className="source-quote">“{text}”</div><button className="text-button" onClick={onReset}>Edit source <Pencil size={14} /></button></div></aside></div><section className="surface-card discovery-summary"><div className="summary-header"><div><div className="card-kicker">READY TO SHARE</div><h3>Customer discovery summary</h3><p>FinBank customer · Mobile banking customer</p></div><Button variant="secondary" onClick={() => onToast("Share dialog opened.")}><Share2 size={15} /> Share discovery</Button></div><div className="summary-grid"><div><span>Customer goal</span><strong>Complete money transfers independently</strong></div><div><span>Root problem</span><strong>Customers lack a simple and reliable way to complete transfers.</strong></div><div><span>Recommended next step</span><strong>Conduct a follow-up interview focused on the money transfer journey.</strong></div></div></section></div>;
}

function ProjectsPage({ navigate, onToast }: { navigate: (path: string) => void; onToast: (message: string) => void }) {
  const [searchTerm, setSearchTerm] = useState("");
  const filtered = projects.filter(p => `${p.name} ${p.customer}`.toLowerCase().includes(searchTerm.toLowerCase()));
  return <><PageHeader eyebrow="CUSTOMER DISCOVERY · WORKSPACE" title="Projects" subtitle="Organize customer discovery work across products, customers, and research initiatives." action={<Button onClick={() => onToast("Create project modal opened.")}><Plus size={16} /> New project</Button>} /><div className="toolbar"><div className="search-field"><Search size={16} /><input placeholder="Search projects" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} /></div><Button variant="secondary"><Filter size={15} /> Filter <ChevronDown size={14} /></Button><Button variant="secondary"><SlidersHorizontalIcon /> Sort</Button></div><div className="projects-grid">{filtered.map(project => <div className="project-card surface-card" key={project.name}><div className="project-card-top"><div className={`project-logo large ${project.tone}`}>{project.name.slice(0, 1)}</div><button><MoreHorizontal size={18} /></button></div><h3>{project.name}</h3><p className="project-customer"><Building2 size={14} /> {project.customer}</p><div className="project-card-stats"><div><span>Conversations</span><strong>{project.conversations}</strong></div><div><span>Problems</span><strong>{project.problems}</strong></div><div><span>Confidence</span><strong>{project.confidence}%</strong></div></div><div className="project-card-bottom"><Badge tone={project.status === "Validated" ? "mint" : project.status === "Needs discovery" ? "amber" : "blue"}>{project.status}</Badge><span>Updated {project.updated}</span></div><Button variant="secondary" className="full-width" onClick={() => navigate("/projects/retail-banking")}>Open project <ArrowRight size={15} /></Button></div>)}<button className="new-project-card" onClick={() => onToast("Create project modal opened.")}><span><Plus size={19} /></span><strong>Create a new project</strong><small>Start a focused discovery workspace</small></button></div></>;
}

function SlidersHorizontalIcon() { return <span className="sliders-icon"><span /><span /><span /></span>; }

function ProjectDetailPage({ navigate, onToast }: { navigate: (path: string) => void; onToast: (message: string) => void }) {
  return <><button className="back-link" onClick={() => navigate("/projects")}><ArrowRight size={15} className="back-arrow" /> Back to projects</button><div className="project-detail-head"><div><div className="eyebrow">PROJECT · ACTIVE DISCOVERY</div><h2>Retail Banking App</h2><p>Helping FinBank customers transfer money with confidence.</p><div className="detail-meta"><span><Building2 size={14} /> FinBank</span><span><Clock3 size={14} /> Started Aug 12, 2026</span><span><Clock3 size={14} /> Updated 2 hours ago</span></div></div><div className="detail-actions"><Button variant="secondary" onClick={() => onToast("Project settings opened.")}><Settings size={15} /> Project settings</Button><Button onClick={() => navigate("/discovery")}><Sparkles size={15} /> New analysis</Button></div></div><div className="detail-stats"><div><span>Conversations</span><strong>8</strong><small>+2 this week</small></div><div><span>Problems discovered</span><strong>4</strong><small>3 high confidence</small></div><div><span>Questions generated</span><strong>22</strong><small>5 unanswered</small></div><div><span>Discovery confidence</span><strong>87%</strong><small>↑ 12% this month</small></div></div><section className="surface-card conversation-list"><div className="card-heading compact"><div><span className="card-kicker">RESEARCH LOG</span><h3>Customer conversations</h3></div><Button variant="secondary" onClick={() => navigate("/discovery")}><Plus size={15} /> Add conversation</Button></div><div className="conversation-list-head"><span>Conversation</span><span>Date</span><span>Status</span><span>Confidence</span><span /></div>{[["Mobile transfer friction", "FinBank customer #08", "Today", "Analyzed", "87%"], ["Card activation journey", "FinBank customer #07", "Sep 06, 2026", "Analyzed", "91%"], ["Receiving a payment", "FinBank customer #06", "Sep 02, 2026", "Analyzed", "82%"], ["International transfer", "FinBank customer #05", "Aug 28, 2026", "Needs review", "64%"]].map(row => <button className="conversation-row" key={row[0]} onClick={() => navigate("/discovery")}><div className="conversation-title"><div className="conversation-row-icon"><MessageSquareText size={15} /></div><div><strong>{row[0]}</strong><span>{row[1]}</span></div></div><span>{row[2]}</span><Badge tone={row[3] === "Analyzed" ? "mint" : "amber"}>{row[3]}</Badge><strong className="confidence-text">{row[4]}</strong><ChevronRight size={16} /></button>)}</section></>;
}

function RequirementsPage({ onToast }: { onToast: (message: string) => void }) {
  const [requirements, setRequirements] = useState([["Customer segment", "Missing", "High"], ["Problem frequency", "Partially known", "High"], ["Current workaround", "Known", "Medium"], ["Business impact", "Missing", "High"], ["Success criteria", "Partially known", "Low"]]);
  return <><PageHeader eyebrow="DISCOVERY REQUIREMENTS" title="What do we still need to know?" subtitle="Track the information you still need to understand the customer problem." action={<Button onClick={() => { setRequirements(r => [["New discovery requirement", "Missing", "Medium"], ...r]); onToast("Requirement added."); }}><Plus size={16} /> Add requirement</Button>} /><div className="requirement-summary"><div className="requirement-summary-score"><span className="card-kicker">DISCOVERY COMPLETENESS</span><strong>62<span>%</span></strong><p>6 of 16 context areas are clear.</p><ProgressBar value={62} color="violet" /></div><div className="requirement-summary-text"><Sparkles size={18} /><p>Fill the high-priority gaps first. The strongest next conversation is usually hiding inside the information you do not have yet.</p></div><div className="requirement-legend"><span><i className="legend-dot known" /> Known <b>1</b></span><span><i className="legend-dot partial" /> Partially known <b>2</b></span><span><i className="legend-dot missing" /> Missing <b>2</b></span></div></div><section className="surface-card requirements-card"><div className="requirements-toolbar"><div><span className="card-kicker">ACTIVE PROJECT · RETAIL BANKING APP</span><h3>Discovery context map</h3></div><Button variant="secondary"><Filter size={14} /> Filter status</Button></div><div className="requirements-table"><div className="requirements-head"><span>Requirement</span><span>Category</span><span>Status</span><span>Priority</span><span>Updated</span><span /></div>{requirements.map(([title, status, priority], index) => <div className="requirement-row" key={`${title}-${index}`}><div className="requirement-name"><div className={`requirement-icon ${status === "Known" ? "known" : status === "Missing" ? "missing" : "partial"}`}>{status === "Known" ? <Check size={14} /> : status === "Missing" ? <AlertCircle size={14} /> : <Clock3 size={14} />}</div><strong>{title}</strong></div><span>{index % 2 === 0 ? "Customer context" : "Problem context"}</span><Badge tone={status === "Known" ? "mint" : status === "Missing" ? "rose" : "amber"}>{status}</Badge><Badge tone={priority === "High" ? "rose" : priority === "Medium" ? "amber" : "slate"}>{priority}</Badge><span className="updated-cell">{index === 0 ? "Today" : `${index + 1}d ago`}</span><div className="row-actions"><button onClick={() => onToast("Requirement marked as validated.")}><Check size={14} /></button><button onClick={() => onToast("Requirement edit opened.")}><Pencil size={14} /></button><button onClick={() => setRequirements(r => r.filter((_, i) => i !== index))}><Trash2 size={14} /></button></div></div>)}</div></section></>;
}

function QuestionsPage({ onToast }: { onToast: (message: string) => void }) {
  const [filter, setFilter] = useState("All questions");
  const [questions, setQuestions] = useState(analysisData.questions.map((q, i) => ({ question: q[0], priority: q[1], purpose: q[2], status: i === 3 ? "Answered" : "Unanswered" })));
  const shown = questions.filter(q => filter === "All questions" || (filter === "High priority" && q.priority === "High") || (filter === "Unanswered" && q.status === "Unanswered") || (filter === "Answered" && q.status === "Answered"));
  return <><PageHeader eyebrow="DISCOVERY QUESTIONS" title="Ask better questions next." subtitle="Manage and organize AI-generated questions for customer interviews." action={<Button onClick={() => { setQuestions(q => [{ question: "What would a successful transfer experience look like?", priority: "Medium", purpose: "Define success criteria.", status: "Unanswered" }, ...q]); onToast("Question added."); }}><Plus size={16} /> Add question</Button>} /><div className="filter-tabs">{["All questions", "High priority", "Unanswered", "Answered"].map(item => <button className={filter === item ? "active" : ""} key={item} onClick={() => setFilter(item)}>{item}<span>{item === "All questions" ? questions.length : questions.filter(q => item === "High priority" ? q.priority === "High" : q.status === item).length}</span></button>)}</div><section className="surface-card question-table-card"><div className="question-table-head"><span>Question</span><span>Priority</span><span>Project</span><span>Status</span><span /></div>{shown.map((q, index) => <div className="question-table-row" key={`${q.question}-${index}`}><div className="question-table-copy"><div className="question-table-number">0{index + 1}</div><div><strong>{q.question}</strong><span>{q.purpose}</span></div></div><Badge tone={q.priority === "High" ? "rose" : "amber"}>{q.priority}</Badge><span className="question-project"><div className="project-logo blue tiny">R</div>Retail Banking App</span><Badge tone={q.status === "Answered" ? "mint" : "slate"}>{q.status}</Badge><div className="row-actions"><button onClick={() => { navigator.clipboard?.writeText(q.question); onToast("Question copied."); }}><Copy size={14} /></button><button onClick={() => onToast("Question edit opened.")}><Pencil size={14} /></button><button onClick={() => setQuestions(items => items.filter(item => item.question !== q.question))}><Trash2 size={14} /></button></div></div>)}</section></>;
}

